const pipeline = staticData.pipeline || {};
const required = ["strategy", "prepKeywords", "clientConfig"];
const missing = required.filter(k => !pipeline[k]);
if (missing.length > 0) {
  throw new Error('Pipeline state missing: ' + missing.join(', ') + '. Run earlier agent(s) first.');
}
return [{ json: pipeline }];

// Output 19 RSS feed objects for the loop
// NOTE: Shares dedupe history with Daily Digest via staticData.contentHistory / digestHistory.
// For persistent cross-workflow dedupe, both workflows reference TOPIC_HISTORY_SHEET_ID (Google Sheet).
// Dead feed removed per audit 2026-04-17 (was AI-News aggregator flagged dead).
const feeds = [{"url": "https://techcrunch.com/category/artificial-intelligence/feed/", "category": "AI", "name": "TechCrunch AI"}, {"url": "https://www.theverge.com/rss/ai-artificial-intelligence/index.xml", "category": "AI", "name": "The Verge AI"}, {"url": "https://feeds.feedburner.com/venturebeat/SZYF", "category": "AI", "name": "VentureBeat"}, {"url": "https://www.technologyreview.com/topic/artificial-intelligence/feed", "category": "AI", "name": "MIT Tech Review"}, {"url": "https://arstechnica.com/feed/", "category": "AI", "name": "Ars Technica"}, {"url": "https://blog.n8n.io/rss/", "category": "AI", "name": "n8n Blog"}, {"url": "https://openai.com/blog/rss.xml", "category": "AI", "name": "OpenAI Blog"}, {"url": "https://www.marktechpost.com/feed/", "category": "AI", "name": "MarkTechPost"}, {"url": "https://hnrss.org/best", "category": "AI", "name": "HN Best"}, {"url": "https://www.nomadicmatt.com/travel-blog/feed/", "category": "Travel", "name": "Nomadic Matt"}, {"url": "https://thepointsguy.com/feed/", "category": "Travel", "name": "The Points Guy"}, {"url": "https://www.skyscanner.net/news/feed/", "category": "Travel", "name": "Skyscanner"}, {"url": "https://www.travelandleisure.com/feeds/all", "category": "Travel", "name": "Travel+Leisure"}, {"url": "https://nomadlist.com/feed", "category": "Travel", "name": "NomadList"}, {"url": "https://smallbiztrends.com/feed", "category": "Business", "name": "Small Biz Trends"}, {"url": "https://www.indiehackers.com/feed.xml", "category": "Business", "name": "Indie Hackers"}, {"url": "https://review.firstround.com/feed.xml", "category": "Business", "name": "First Round Review"}, {"url": "https://www.saastr.com/feed/", "category": "Business", "name": "SaaStr"}, {"url": "https://hbr.org/feed", "category": "Business", "name": "HBR"}];
return feeds.map(f => ({ json: f }));

// Extract stories from all fetched RSS feeds, filter to last 7 days
const items = $input.all();
const stories = [];
const now = Date.now();
const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

// Dedup against content history
const staticData = $getWorkflowStaticData('global');
const history = staticData.contentHistory || [];
const usedUrls = new Set(history.slice(-4).flatMap(h => h.storyUrls || []));

for (const item of items) {
  const feedName = item.json.name || 'Unknown';
  const feedCategory = item.json.category || 'AI';
  const raw = item.json.data || item.json.body || '';
  if (!raw || typeof raw !== 'string' || raw.length < 50) continue;

  const itemRegex = /<item[\s>][\s\S]*?<\/item>|<entry[\s>][\s\S]*?<\/entry>/gi;
  const matches = raw.match(itemRegex) || [];
  for (const m of matches) {
    const title = (m.match(/<title[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s) || [])[1] || '';
    const link = (m.match(/<link[^>]*href="([^"]*)"/) || m.match(/<link[^>]*>(.*?)<\/link>/) || [])[1] || '';
    const desc = (m.match(/<description[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s) ||
                  m.match(/<summary[^>]*>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/summary>/s) || [])[1] || '';
    const pubDate = (m.match(/<pubDate[^>]*>(.*?)<\/pubDate>/) ||
                     m.match(/<published[^>]*>(.*?)<\/published>/) || [])[1] || '';
    const ts = pubDate ? new Date(pubDate).getTime() : 0;
    if (ts && (now - ts) > WEEK_MS) continue;
    if (link && usedUrls.has(link)) continue;
    const cleanDesc = desc.replace(/<[^>]*>/g, '').substring(0, 200);
    stories.push({ title: title.trim(), link: link.trim(), description: cleanDesc.trim(), pubDate, source: feedName, category: feedCategory });
  }
}

// Deduplicate
const seen = new Set();
const unique = stories.filter(s => {
  if (!s.link || seen.has(s.link)) return false;
  seen.add(s.link);
  return true;
});
unique.sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));
const top50 = unique.slice(0, 50);

// Format as CSV text for Gemini
let csv = 'rank,title,source,category,url,description\n';
top50.forEach((s, i) => {
  csv += `${i+1},"${s.title.replace(/"/g, '""')}","${s.source}","${s.category}","${s.link}","${s.description.replace(/"/g, '""')}"\n`;
});

return [{ json: { csvData: csv, storyCount: top50.length, stories: top50 } }];

